 "content": "def transform(grid):
    out=[r[:] for r in grid]
    R,C=len(grid),len(grid[0])
    # identify the long bars, and fill the missing cells in each bar
    bars=[]
    for r,row in enumerate(grid):
        nz=[c for c,v in enumerate(row) if v]
        if len(nz)>=3 and nz[-1]-nz[0]>=5:
            bars.append((r,nz[0],nz[-1]))
            # bar color is most common value; gaps take the adjacent matching color
            from collections import Counter
            color=Counter(row[c] for c in nz).most_common(1)[0][0]
            for c in range(nz[0],nz[-1]+1):
                if row[c]==0: out[r][c]=color
    # vertical marks are columns having an independent seed below the bars.
    # They extend upward to the nearest bar that has a gap at that column.
    for r,lo,hi in bars:
        for c in range(lo,hi+1):
            if grid[r][c]!=0: continue
            seeds=[y for y in range(r+1,R) if grid[y][c]]
            if seeds:
                color=grid[seeds[0]][c]
                for y in range(r):
                    if out[y][c]==0: out[y][c]=color
    return out
